    private List<SerialIntervals.Interval> normalizeSpecs(List<IntervalSpec> specs) {
        List<int[]> raw = new ArrayList<>(specs.size());
        for (IntervalSpec spec : specs) {
            raw.add(new int[]{spec.start(), spec.end()});
